//go:build linux
package projectaccess
import("context";"errors";"os";"path/filepath";"testing")
func TestScratchConfigurationOwnerAndAncestorPolicy(t *testing.T){path:=t.TempDir();if err:=os.Chmod(path,0700);err!=nil{t.Fatal(err)};if !safeScratch(path){t.Fatal("private scratch refused")};ancestor:=filepath.Join(path,"writable");scratch:=filepath.Join(ancestor,"scratch");if err:=os.MkdirAll(scratch,0700);err!=nil{t.Fatal(err)};if err:=os.Chmod(ancestor,0777);err!=nil{t.Fatal(err)};if safeScratch(scratch){t.Fatal("unsafe writable ancestor admitted")};if err:=os.Chmod(ancestor,0700);err!=nil{t.Fatal(err)};if !safeScratch(scratch){t.Fatal("safe scratch denied")}}
func TestScratchConfigurationForeignOwnerRejectedWithoutRepair(t *testing.T){if os.Geteuid()!=0{t.Skip("foreign-owner ownership fixture requires root; unprivileged mode/ancestor cases run separately")};c:=accessFixture(t);if err:=os.Chown(c.ScratchParent,65534,65534);err!=nil{t.Fatal(err)};defer os.Chown(c.ScratchParent,0,0);if safeScratch(c.ScratchParent){t.Fatal("foreign scratch admitted")};report,err:=Preflight(context.Background(),c);if !errors.Is(err,ErrFilesystem)||report.ProjectID!=""{t.Fatal(report,err)};entries,err:=os.ReadDir(c.ScratchParent);if err!=nil||len(entries)!=0{t.Fatal(entries,err)}}
